import os
import django
from django.conf import settings
from django.db import models
from django.forms import ModelForm
from django.forms.models import construct_instance

# Configure Django settings
if not settings.configured:
    settings.configure(
        DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
        INSTALLED_APPS=['test_app'],
    )
    django.setup()

# We need to define the model within a registered app.
from django.apps import apps

class MyModel(models.Model):
    my_field = models.CharField(max_length=100, default='default_value', blank=True)

    class Meta:
        app_label = 'test_app'

class MyModelForm(ModelForm):
    class Meta:
        model = MyModel
        fields = ['my_field']

def test_reproduction():
    # Case 3: Field is NOT in data, no clean() override
    data = {}
    form = MyModelForm(data=data)
    if form.is_valid():
        print(f"Case 3 Cleaned data: {form.cleaned_data}")
        instance = MyModel()
        instance = construct_instance(form, instance)
        print(f"Case 3 (not in data, no clean): Expected 'default_value', got '{instance.my_field}'")
        assert instance.my_field == 'default_value'

if __name__ == "__main__":
    try:
        test_reproduction()
        print("Tests passed!")
    except AssertionError as e:
        print(f"Test failed!")
    except Exception as e:
        print(f"An error occurred: {e}")
